type Tab = "today" | "echo" | "stampbook";
type TaskStatus = "ready" | "active" | "completed" | "partial" | "continued";
type FocusStatus = "idle" | "running" | "paused";
type TaskKind = "reading" | "exercise" | "coding" | "offline" | "custom";
type TaskColor = "sage" | "peach" | "yellow";
type OutcomeKind = "summary" | "answer" | "file" | "self-report";
type OutcomeClassification = "completed" | "partial" | "continued";
type NoteType = "result" | "continued" | "blocker" | "idea" | "source" | "milestone" | "pause";
type FocusMode = "short" | "standard" | "free";

type Task = {
  id: string;
  title: string;
  subject: string;
  duration: string;
  planMinutes: number;
  actualMs: number;
  status: TaskStatus;
  color: TaskColor;
  kind: TaskKind;
  expectedArtifact: string;
  milestoneId?: string;
  revisionCount: number;
};

type FocusSession = { activeTaskId: string | null; status: FocusStatus; startedAt: number | null; resumeNote?: string };
type FocusLog = { id: string; dateKey: string; taskId: string; startedAt: number; endedAt: number; durationMs: number };
type DiaryEntry = { id: string; dateKey: string; text: string; createdAt: number; updatedAt: number };
type DayRecord = { dateKey: string; diary?: DiaryEntry; outcomes: Outcome[]; notes: FootprintNote[]; echo?: DailyEchoDraft; focusMs: number };
type Outcome = { id: string; taskId: string; dateKey: string; classification: OutcomeClassification; evidenceType: OutcomeKind; body: string; nextStep?: string; createdAt: number; version: number };
type FootprintNote = { id: string; type: NoteType; title: string; body: string; color: TaskColor | "blue" | "purple"; dateKey: string; createdAt: number; taskId?: string; outcomeId?: string; milestoneId?: string; sourceUrl?: string; pinned: boolean; archived?: boolean };
type Milestone = { id: string; title: string; criteria: string; scene: string; unlocked: boolean; unlockedByOutcomeId?: string };
type Blocker = { id: string; taskId: string | null; label: string; dateKey: string; createdAt: number };
type TomorrowExperiment = { id: string; title: string; source: string; status: "planned" | "done"; dateKey: string; createdAt: number };
type SourceRef = { label: string; url: string; createdAt: number };
type StampPrompt = { taskId: string; scopeKey: string; dateKey: string; completionId: string; createdAt: number };
type StampBookState = { version: number; styleAssignments: Record<string, StampStyleChoice>; pendingSetup?: StampPrompt };
type Preferences = { focusMode: FocusMode; reminderEnabled: boolean; echoTime: string; includeDiaryInAI: boolean; zhihuMatching: boolean; zhihuConnected: boolean; reduceMotion: boolean; theme: "paper" };
type PersistedState = { version: 5; tasks: Task[]; focusSession: FocusSession; focusLedger: Record<string, number>; focusLogs: FocusLog[]; outcomes: Outcome[]; diaries: DiaryEntry[]; dailyEchoes: Record<string, DailyEchoDraft>; weeklyEchoes: WeeklyEchoDraft[]; notes: FootprintNote[]; milestones: Milestone[]; blockers: Blocker[]; experiments: TomorrowExperiment[]; sourceRef: SourceRef | null; methodNote: string; preferences: Preferences; stampStyles: Record<string, StampStyleChoice>; stampBook: StampBookState };

