function createId(prefix: string) { if (typeof crypto !== "undefined" && "randomUUID" in crypto) return `${prefix}-${crypto.randomUUID()}`; return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function daysAgo(days: number) { const date = new Date(); date.setDate(date.getDate() - days); return date.getTime(); }
function formatDate(timestamp = Date.now()) { return new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric", weekday: "long" }).format(new Date(timestamp)); }
function formatDay(timestamp: number) { return new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric", weekday: "short" }).format(new Date(timestamp)); }
function formatElapsed(ms: number) { const totalSeconds = Math.max(0, Math.floor(ms / 1000)); return `${Math.floor(totalSeconds / 60).toString().padStart(2, "0")}:${(totalSeconds % 60).toString().padStart(2, "0")}`; }
function formatMinutes(ms: number) { return ms < 60_000 ? `${Math.floor(ms / 1000)} 秒` : `${Math.round(ms / 60_000)} 分钟`; }
function formatTaskDuration(ms: number) { const totalSeconds = Math.max(0, Math.floor(ms / 1000)); const minutes = Math.floor(totalSeconds / 60); const seconds = totalSeconds % 60; return minutes ? `${minutes}分${seconds ? `${seconds}秒` : "钟"}` : `${seconds}秒`; }
