function noteLabel(type: NoteType) { return { result: "成果", continued: "继续点", pause: "投入记录", blocker: "卡点", idea: "想法", source: "来源", milestone: "里程碑" }[type]; }
function classificationLabel(value: OutcomeClassification) { return { completed: "已完成", partial: "部分完成", continued: "留到明天" }[value]; }
function stampGlyphText(icon: StampIcon, source: string) { return icon === "source" ? source.slice(0, 5) : icon === "book" ? "▤" : icon === "atom" ? "⚛" : icon === "flask" ? "⚗" : icon === "english" ? "En" : icon === "leaf" ? "⌁" : icon === "pen" ? "✎" : icon === "mountain" ? "⌂" : icon === "coffee" ? "☕" : "✦"; }
function stampClass(style: StampStyleChoice, filled = true) { return `stamp-mark ${style.outline} ${style.color} ${filled ? "filled" : "outline"}`; }
function defaultPreferences(): Preferences { return { focusMode: "short", reminderEnabled: true, echoTime: "21:30", includeDiaryInAI: true, zhihuMatching: false, zhihuConnected: false, reduceMotion: false, theme: "paper" }; }

